var n=`0996-scallion-beef-rolls`;var t=`world-0996`;var s=`TW`;var o=`east-asia`;var a=4;var l=69;var r={en:`Scallion Beef Rolls`,ua:`Яловичі рулетики із зеленою цибулею`};var u={en:`Scallion Beef Rolls is a Taiwan dish made with all-purpose flour, green onion, beef sirloin, hoisin sauce. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Яловичі рулетики із зеленою цибулею, страва кухні країни Тайвань. Основні складники: пшеничне борошно універсальне, зелена цибуля, яловичий сирлойн, соус хойсин. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,370,`g`],[`water`,205,`ml`],[`table-salt`,5,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:14,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 16 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 16 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:16,i:[[`canola-oil`,40,`ml`],[`green-onion`,125,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`beef-sirloin`,520,`g`],[`hoisin-sauce`,75,`g`],[`light-soy-sauce`,45,`ml`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:8,i:[[`cucumber`,180,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,18,`g`]]}];var g={slug:n,id:t,country:`TW`,region:o,servings:4,minutes:69,title:r,text:u,steps:d};export{s as country,g as default,t as id,l as minutes,o as region,a as servings,n as slug,d as steps,u as text,r as title};